  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  code STRING(64) NOT NULL,
  name_i18n JSONB NOT NULL,
  sort_order INT4 NOT NULL DEFAULT 0,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_account_status PRIMARY KEY (id),
  CONSTRAINT uq_account_status_code UNIQUE (code),
  CONSTRAINT ck_account_status_code_format CHECK (code ~ '^[a-z0-9_]+$'),
  CONSTRAINT ck_account_status_name_i18n_en CHECK (name_i18n ? 'en')
);
